settings.custom_liquid:
{% comment %} Pobranie pliku z metapola {% endcomment %}
{% assign skin_report = customer.metafields.custom.testowyplik2.value %}

{% if skin_report %}
<style>
  /* Import czcionki Barlow (jeśli nie jest jeszcze załadowana w motywie) */
  @import url('https://fonts.googleapis.com/css2?family=Barlow:wght@400;700&display=swap');

  .skin-report-container {
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 30px 15px;
    font-family: 'Barlow', sans-serif;
    text-align: center;
  }

  .skin-report-content {
    max-width: 450px;
    width: 100%;
  }

  .skin-report-content h4 {
    font-family: 'Barlow', sans-serif !important;
    font-size: 18px !important; /* Zmniejszony font nagłówka */
    font-weight: 700 !important; /* Wyboldowanie */
    margin: 0 0 10px 0 !important;
    color: #000;
    line-height: 1.4;
    text-transform: none;
  }

  .skin-report-text {
    font-size: 14px;
    color: #555;
    margin: 0 0 20px 0;
  }

  .skin-report-btn-wrapper {
    display: flex;
    justify-content: center;
  }

  .skin-report-download-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    background-color: #000;
    color: #fff !important;
    text-decoration: none !important;
    padding: 12px 28px;
    border-radius: 4px;
    font-weight: 600;
    font-size: 14px;
    transition: opacity 0.2s ease;
  }

  .skin-report-download-btn:hover {
    opacity: 0.8;
  }

  .skin-report-download-btn svg {
    flex-shrink: 0;
  }
</style>

<div class="skin-report-container">
  <div class="skin-report-content">
    <h4>Raport z Twojego badania skóry jest już dostępny!</h4>
    <p class="skin-report-text">Pobierz go teraz:</p>

    <div class="skin-report-btn-wrapper">
      <a href="{{ skin_report.url }}" class="skin-report-download-btn" target="_blank" download="Raport_Skory">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v4"></path>
          <polyline points="7 10 12 15 17 10"></polyline>
          <line x1="12" y1="15" x2="12" y2="3"></line>
        </svg>
        Pobierz Raport (PDF)
      </a>
    </div>
  </div>
</div>
{% endif %}
